using System;
using System.IO;
using System.Linq;
using System.Drawing;
using System.Collections.Generic;
using System.Windows.Forms;

public static class DeviceReferences {
 public static HlbDocument Current;
 static string Part(HlbDocument doc,string field,string value){value=(value??"").Trim();Dictionary<string,string> codes;string code;if(doc.Mnemonics.TryGetValue(field,out codes)&&codes.TryGetValue(value,out code)&&!String.IsNullOrWhiteSpace(code))value=code;return value.Length==0?"Unspecified":value.Replace('/','-').Replace('\\','-');}
 public static string Prefix(HlbDocument doc,Device d){return Part(doc,"Category",d.Group)+"/"+Part(doc,"Device type",Ui.Detail(d,"Device type"))+"/"+Part(doc,"Location",Ui.Detail(d,"Location"));}
 static int Number(string reference,string prefix){int n;string start=prefix+"/";return reference.StartsWith(start,StringComparison.OrdinalIgnoreCase)&&Int32.TryParse(reference.Substring(start.Length),out n)&&n>0?n:0;}
 public static string Preview(HlbDocument doc,Device d){if(doc==null)doc=new HlbDocument();string prefix=Prefix(doc,d),existing=Ui.Detail(d,"Device reference");if(Number(existing,prefix)>0&&!doc.Devices.Any(x=>x.Id!=d.Id&&String.Equals(Ui.Detail(x,"Device reference"),existing,StringComparison.OrdinalIgnoreCase)))return existing;int n;doc.ReferenceCounters.TryGetValue(prefix,out n);n=Math.Max(n,doc.Devices.Where(x=>x.Id!=d.Id).Select(x=>Number(Ui.Detail(x,"Device reference"),prefix)).DefaultIfEmpty(0).Max());return prefix+"/"+checked(n+1);}
 public static bool Assign(HlbDocument doc){bool changed=false;var used=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var pending=new List<Device>();foreach(var d in doc.Devices){string prefix=Prefix(doc,d),reference=Ui.Detail(d,"Device reference");int n=Number(reference,prefix),max;doc.ReferenceCounters.TryGetValue(prefix,out max);if(n>0&&used.Add(reference)){doc.ReferenceCounters[prefix]=Math.Max(max,n);}else pending.Add(d);}
  foreach(var d in pending){string prefix=Prefix(doc,d);int max;doc.ReferenceCounters.TryGetValue(prefix,out max);string value;do{max=checked(max+1);value=prefix+"/"+max;}while(!used.Add(value));string old=Ui.Detail(d,"Device reference");if(old.Length>0&&old!=value){string history=Ui.Detail(d,"Previous device references");d.Details["Previous device references"]=history.Length==0?old:history+"\r\n"+old;}d.Details["Device reference"]=value;doc.ReferenceCounters[prefix]=max;changed=true;}return changed;
 }
}
public class LookupRow {public string Original,Description,Mnemonic;}
public static class ListChanges {
 public static bool Used(HlbDocument doc,string field,string value){return doc.Devices.Any(d=>field=="Category"?d.Group==value:field=="Connectivity"?d.Connections.Any(c=>c.Connectivity==value):field=="IP range"?d.Connections.Any(c=>DeviceConnections.Get(c.Details,field)==value):Ui.Detail(d,field)==value);}
 public static void Apply(HlbDocument doc,string field,List<LookupRow> rows){if(rows.Count>LookupStore.MaxEntries)throw new Exception("A list can contain up to "+LookupStore.MaxEntries+" entries.");var names=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var codes=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var row in rows){row.Description=(row.Description??"").Trim();row.Mnemonic=(row.Mnemonic??"").Trim();if(row.Description.Length==0||row.Description.Length>(field=="Category"?60:100)||row.Description.Any(Char.IsControl))throw new Exception("Descriptions must be non-empty, single-line values (up to "+(field=="Category"?60:100)+" characters).");if(!names.Add(row.Description))throw new Exception("Each description must be unique.");if(row.Mnemonic.Length>30||row.Mnemonic.IndexOfAny(new[]{'/','\\'})>=0||row.Mnemonic.Any(Char.IsControl))throw new Exception("Mnemonics must be up to 30 characters and cannot contain slashes or line breaks.");if(row.Mnemonic.Length>0&&!codes.Add(row.Mnemonic))throw new Exception("Each mnemonic in a list must be unique.");}
  foreach(var old in doc.Lookups[field])if(!rows.Any(r=>r.Original==old)&&Used(doc,field,old))throw new Exception("'"+old+"' is used by a device. Change that device before removing this entry.");var rename=rows.Where(r=>r.Original!=null).ToDictionary(r=>r.Original,r=>r.Description);Func<string,string> replace=value=>value!=null&&rename.ContainsKey(value)?rename[value]:value;
  foreach(var d in doc.Devices){if(field=="Category")d.Group=replace(d.Group);else if(field=="Connectivity")foreach(var c in d.Connections)c.Connectivity=replace(c.Connectivity);else if(field=="IP range"){foreach(var c in d.Connections)if(c.Details.ContainsKey(field))c.Details[field]=replace(c.Details[field]);}else if(d.Details.ContainsKey(field))d.Details[field]=replace(d.Details[field]);}
  doc.Lookups[field]=rows.Select(r=>r.Description).ToList();doc.Mnemonics[field]=rows.Where(r=>r.Mnemonic.Length>0).ToDictionary(r=>r.Description,r=>r.Mnemonic);
 }
}
public class LookupListEditor:Form {
 public HlbDocument Value;HlbDocument draft;ComboBox selector;DataGridView grid;Label countLabel;string field;bool switching;
 public LookupListEditor(HlbDocument source,string chosen){draft=HlbFile.Decode(HlbFile.Encode(source));Text="List Editor";ClientSize=new Size(620,490);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;MinimizeBox=false;StartPosition=FormStartPosition.CenterParent;BackColor=Dashboard.Bg;ForeColor=Dashboard.Ink;Font=new Font("Segoe UI",10);
  Ui.Label(this,"List",20,24,42,25,Dashboard.Muted);selector=new ComboBox{Location=new Point(62,20),Width=275,DropDownStyle=ComboBoxStyle.DropDownList,BackColor=Dashboard.PanelBg,ForeColor=Dashboard.Ink};selector.Items.AddRange(draft.Lookups.Keys.OrderBy(x=>x).Cast<object>().ToArray());Controls.Add(selector);
  var add=Dashboard.Btn("+",()=>{if(grid.Rows.Count>=LookupStore.MaxEntries){MessageBox.Show("A list can contain up to "+LookupStore.MaxEntries+" entries.");return;}grid.EndEdit();int i=grid.Rows.Add("","");grid.CurrentCell=grid.Rows[i].Cells[0];grid.BeginEdit(true);});add.AccessibleName="Add row";add.Width=38;add.AutoSize=false;add.Location=new Point(350,18);Controls.Add(add);var remove=Dashboard.Btn("−",()=>{if(grid.CurrentRow==null)return;string old=grid.CurrentRow.Tag as string;if(old!=null&&ListChanges.Used(draft,field,old)){MessageBox.Show(this,"This entry is used by a device. Change that device before removing it.","Entry in use");return;}grid.Rows.Remove(grid.CurrentRow);});remove.AccessibleName="Remove selected row";remove.Width=38;remove.AutoSize=false;remove.Location=new Point(395,18);Controls.Add(remove);
  grid=new DataGridView{Location=new Point(20,70),Size=new Size(580,310),AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,MultiSelect=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,BackgroundColor=Dashboard.PanelBg,BorderStyle=BorderStyle.None,EnableHeadersVisualStyles=false,SelectionMode=DataGridViewSelectionMode.CellSelect};grid.ColumnHeadersDefaultCellStyle.BackColor=Dashboard.PanelBg;grid.ColumnHeadersDefaultCellStyle.ForeColor=Dashboard.Accent;grid.DefaultCellStyle.BackColor=Dashboard.PanelBg;grid.DefaultCellStyle.ForeColor=Dashboard.Ink;grid.DefaultCellStyle.SelectionBackColor=Color.FromArgb(40,83,92);grid.DefaultCellStyle.SelectionForeColor=Dashboard.Ink;grid.GridColor=Color.FromArgb(53,68,87);grid.ScrollBars=ScrollBars.Both;grid.Columns.Add("Description","Description");grid.Columns.Add("Mnemonic","Mnemonic");grid.Columns[0].FillWeight=70;grid.Columns[1].FillWeight=30;Controls.Add(grid);countLabel=Ui.Label(this,"",20,450,450,25,Dashboard.Muted,9);grid.RowsAdded+=(s,e)=>UpdateCount();grid.RowsRemoved+=(s,e)=>UpdateCount();
  Ui.Label(this,"Reference: <Category>/<Device Type>/<Location>/<No>\r\nUses mnemonics when supplied; otherwise descriptions.",20,395,580,48,Dashboard.Muted,9);var save=Dashboard.Btn("Save",()=>{try{StoreRows();Value=draft;DialogResult=DialogResult.OK;}catch(Exception ex){MessageBox.Show(this,ex.Message,"Check list");}});save.Location=new Point(440,18);Controls.Add(save);var cancel=Dashboard.Btn("Cancel",()=>DialogResult=DialogResult.Cancel);cancel.Location=new Point(525,443);Controls.Add(cancel);CancelButton=cancel;
  selector.SelectedIndexChanged+=(s,e)=>{if(switching)return;string next=selector.Text;try{if(field!=null)StoreRows();LoadRows(next);}catch(Exception ex){MessageBox.Show(this,ex.Message,"Check list before switching");switching=true;selector.SelectedItem=field;switching=false;}};selector.SelectedItem=chosen;if(selector.SelectedIndex<0)selector.SelectedIndex=0;
 }
 void UpdateCount(){countLabel.Text=grid.Rows.Count+" / "+LookupStore.MaxEntries+" entries · scroll to view all rows";}
 void StoreRows(){grid.EndEdit();var rows=grid.Rows.Cast<DataGridViewRow>().Select(r=>new LookupRow{Original=r.Tag as string,Description=Convert.ToString(r.Cells[0].Value),Mnemonic=Convert.ToString(r.Cells[1].Value)}).ToList();ListChanges.Apply(draft,field,rows);foreach(DataGridViewRow row in grid.Rows)row.Tag=Convert.ToString(row.Cells[0].Value).Trim();}
 void LoadRows(string name){field=name;grid.Rows.Clear();Dictionary<string,string> codes;draft.Mnemonics.TryGetValue(field,out codes);foreach(var item in draft.Lookups[field]){string code="";if(codes!=null)codes.TryGetValue(item,out code);int i=grid.Rows.Add(item,code);grid.Rows[i].Tag=item;}}
}
public class SettingsDialog:Form {
 public UiPreferences Value;public HlbDocument NetworkValue;HlbDocument draft;
 public SettingsDialog(HlbDocument source=null,Action<HlbDocument> saveLists=null){draft=HlbFile.Decode(HlbFile.Encode(source??new HlbDocument{Preferences=UiPreferences.Current}));var p=UiPreferences.Current;Text="Settings";ClientSize=new Size(610,575);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;MinimizeBox=false;StartPosition=FormStartPosition.CenterParent;BackColor=Dashboard.Bg;ForeColor=Dashboard.Ink;Font=new Font("Segoe UI",10);
  Ui.Label(this,"Dashboard",20,16,550,28,Dashboard.Accent,12,true);Ui.Label(this,"Default view",30,55,145,25,Dashboard.Muted);var view=new ComboBox{Location=new Point(180,52),Width=395,DropDownStyle=ComboBoxStyle.DropDownList,BackColor=Dashboard.PanelBg,ForeColor=Dashboard.Ink};view.Items.AddRange(new[]{"Tiles","List","Layout"});view.SelectedItem=p.View;Controls.Add(view);Ui.Label(this,"Default zoom",30,94,145,25,Dashboard.Muted);var zoom=new ComboBox{Location=new Point(180,91),Width=395,DropDownStyle=ComboBoxStyle.DropDownList,BackColor=Dashboard.PanelBg,ForeColor=Dashboard.Ink};for(int i=20;i<=200;i+=10)zoom.Items.Add(i+"%");string current=p.Zoom+"%";if(!zoom.Items.Contains(current))zoom.Items.Add(current);zoom.SelectedItem=current;Controls.Add(zoom);
  Ui.Label(this,"External Viewers",20,148,550,28,Dashboard.Accent,12,true);Ui.Label(this,"Executable name or full path",30,178,540,23,Dashboard.Muted,9);var ssh=Viewer("SSH",p.SshClient,210);var rdp=Viewer("RDP",p.RdpClient,250);
  Ui.Label(this,"List Editor",20,308,550,28,Dashboard.Accent,12,true);Ui.Label(this,"List",30,350,80,25,Dashboard.Muted);var list=new ComboBox{Location=new Point(110,346),Width=370,DropDownStyle=ComboBoxStyle.DropDownList,BackColor=Dashboard.PanelBg,ForeColor=Dashboard.Ink};list.Items.AddRange(draft.Lookups.Keys.OrderBy(x=>x).Cast<object>().ToArray());list.SelectedIndex=0;Controls.Add(list);var edit=Dashboard.Btn("Edit",()=>{using(var f=new LookupListEditor(draft,list.Text)){if(f.ShowDialog(this)==DialogResult.OK){if(saveLists!=null)saveLists(f.Value);draft=f.Value;}}});edit.Location=new Point(495,343);Controls.Add(edit);
  Ui.Label(this,"Defaults for new connections",20,396,550,25,Dashboard.Accent,10,true);Ui.Label(this,"SSH port",30,431,80,25,Dashboard.Muted);var port=new NumericUpDown{Location=new Point(110,428),Width=100,Minimum=1,Maximum=65535,Value=p.SshPort};Controls.Add(port);Ui.Label(this,"Share",235,431,65,25,Dashboard.Muted);var share=new TextBox{Location=new Point(300,428),Width=275,Text=p.Share,BackColor=Dashboard.PanelBg,ForeColor=Dashboard.Ink};Controls.Add(share);Ui.Label(this,"Save applies software settings on this computer.\r\nList Editor Save applies lists; Menu > Save writes the .hlb.",20,478,570,42,Dashboard.Muted,9);
  var save=Dashboard.Btn("Save",()=>{try{if(String.IsNullOrWhiteSpace(ssh.Text)||String.IsNullOrWhiteSpace(rdp.Text))throw new Exception("Enter the SSH and RDP executable names.");int z=Int32.Parse(zoom.Text.TrimEnd('%'));if(view.Text!="Layout"&&(z<60||z>150))throw new Exception("Tiles and List zoom must be between 60% and 150%.");var check=new AccessOptions{SharePath=share.Text};check.Validate();Value=new UiPreferences{View=view.Text,Zoom=z,SshClient=ssh.Text.Trim(),RdpClient=rdp.Text.Trim(),SshPort=(int)port.Value,Share=check.SharePath};draft.Preferences=Value;DeviceReferences.Assign(draft);NetworkValue=draft;DialogResult=DialogResult.OK;}catch(Exception ex){MessageBox.Show(this,ex.Message,"Check settings");}});save.Location=new Point(405,530);Controls.Add(save);var cancel=Dashboard.Btn("Cancel",()=>DialogResult=DialogResult.Cancel);cancel.Location=new Point(505,530);Controls.Add(cancel);CancelButton=cancel;
 }
 TextBox Viewer(string title,string value,int y){Ui.Label(this,title,30,y+4,75,25,Dashboard.Muted);var box=new TextBox{Location=new Point(110,y),Width=370,Text=value,BackColor=Dashboard.PanelBg,ForeColor=Dashboard.Ink};Controls.Add(box);var find=Dashboard.Btn("Find",()=>{using(var f=new OpenFileDialog{Title="Find "+title+" executable",Filter="Applications (*.exe)|*.exe|All files|*.*"})if(f.ShowDialog(this)==DialogResult.OK)box.Text=f.FileName;});find.Location=new Point(495,y-3);Controls.Add(find);return box;}
}
